select tu.id as id, tu.team_id as teamId, tu.user_id as userId, cu.avatar as avatar, cu.nickname as nickName, tu.user_name as userName, tu.user_phone as userPhone, tu.department_id as departmentId, td.name as departmentName, tu.healthy_coin as healthyCoin, tu.join_type as joinType, tu.status as status,tu.type as type,tu.delete_time from team_user as tu left join cas_user as cu on tu.user_id = cu.id left join team_department as td on tu.department_id = td.id and td.delete_time is null
and tu.team_id = #{param.teamId}
and tu.user_name like concat('%', #{param.userName}, '%')
and tu.user_phone like concat('%', #{param.userPhone}, '%')
AND (tu.user_name LIKE CONCAT('%',#{param.keyword},'%') OR tu.user_phone LIKE CONCAT('%',#{param.keyword},'%') OR cu.nickname LIKE CONCAT('%',#{param.keyword},'%'))
and tu.type = #{param.type}
and tu.status = #{param.status}
and tu.department_id = #{param.departmentId}
and tu.department_id IS NULL
and tu.delete_time is null
order by tu.id desc

